import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import io from 'socket.io-client';
import './DMPage.css';

const DMPage = () => {
  const [conversations, setConversations] = useState([]);
  const [selectedConversation, setSelectedConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const [socket, setSocket] = useState(null);
  const messagesEndRef = useRef(null);
  const navigate = useNavigate();

  // Initialize socket connection
  useEffect(() => {
    const token = localStorage.getItem('token');
    const newSocket = io('http://localhost:5001', {
      auth: { token },
      transports: ['websocket']
    });

    newSocket.on('connect', () => {
      console.log('Socket connected');
      setSocket(newSocket);
    });

    newSocket.on('disconnect', () => {
      console.log('Socket disconnected');
    });

    return () => newSocket.disconnect();
  }, []);

  // Fetch conversations
  useEffect(() => {
    const fetchConversations = async () => {
      try {
        const token = localStorage.getItem('token');
        const res = await fetch('http://localhost:5001/api/conversations', {
          headers: { Authorization: `Bearer ${token}` }
        });

        if (!res.ok) throw new Error('Failed to fetch conversations');

        const { data } = await res.json();
        setConversations(data);
      } catch (err) {
        console.error('Error:', err);
      } finally {
        setLoading(false);
      }
    };

    fetchConversations();
  }, []);

  // Fetch messages when conversation is selected
  useEffect(() => {
    if (!selectedConversation) return;

    const fetchMessages = async () => {
      try {
        const token = localStorage.getItem('token');
        const res = await fetch(
          `http://localhost:5001/api/conversations/${selectedConversation._id}/messages`,
          { headers: { Authorization: `Bearer ${token}` } }
        );

        if (!res.ok) throw new Error('Failed to fetch messages');

        const { data } = await res.json();
        setMessages(data);
      } catch (err) {
        console.error('Error:', err);
      }
    };

    fetchMessages();
  }, [selectedConversation]);

  // Auto-scroll to bottom of messages
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Socket event listeners
  useEffect(() => {
    if (!socket) return;

    const handleNewMessage = (message) => {
      if (selectedConversation && message.conversationId === selectedConversation._id) {
        setMessages(prev => [...prev, message]);
      }
      // Update last message in conversations list
      setConversations(prev => prev.map(conv => 
        conv._id === message.conversationId 
          ? { ...conv, lastMessage: message } 
          : conv
      ));
    };

    socket.on('newMessage', handleNewMessage);

    return () => {
      socket.off('newMessage', handleNewMessage);
    };
  }, [socket, selectedConversation]);

  const handleSendMessage = async () => {
    if (!newMessage.trim() || !selectedConversation || !socket) return;

    try {
      const token = localStorage.getItem('token');
      const user = JSON.parse(localStorage.getItem('user'));

      // Optimistic UI update
      const tempId = Date.now();
      const tempMessage = {
        _id: tempId,
        sender: { _id: user._id, name: user.name, image: user.image },
        text: newMessage,
        timestamp: new Date(),
        isOptimistic: true
      };

      setMessages(prev => [...prev, tempMessage]);
      setNewMessage('');

      // Send to server
      const res = await fetch(
        `http://localhost:5001/api/conversations/${selectedConversation._id}/messages`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`
          },
          body: JSON.stringify({ text: newMessage })
        }
      );

      if (!res.ok) throw new Error('Failed to send message');

      const { data } = await res.json();

      // Replace optimistic message with real one
      setMessages(prev => [
        ...prev.filter(m => m._id !== tempId),
        data
      ]);

      // Emit socket event
      const otherParticipant = selectedConversation.participants[0];
      socket.emit('sendMessage', {
        conversationId: selectedConversation._id,
        sender: user._id,
        receiver: otherParticipant._id,
        text: newMessage
      });
    } catch (err) {
      console.error('Error:', err);
      // Remove optimistic message if failed
      setMessages(prev => prev.filter(m => !m.isOptimistic));
    }
  };

  if (loading) return (
    <div className="loading-screen">
      <div className="spinner"></div>
      <p>Loading your conversations...</p>
    </div>
  );

  return (
    <div className="dm-container">
      {/* Left sidebar - Conversation list */}
      <div className="conversation-list">
        <div className="conversation-header">
          <h2>Messages</h2>
          <div className="search-bar">
            <input type="text" placeholder="Search conversations..." />
          </div>
        </div>

        {conversations.length === 0 ? (
          <div className="empty-state">
            <p>No conversations yet</p>
          </div>
        ) : (
          <div className="conversation-items">
            {conversations.map((conv) => (
              <div
                key={conv._id}
                className={`conversation-item ${selectedConversation?._id === conv._id ? 'active' : ''}`}
                onClick={() => setSelectedConversation(conv)}
              >
                <div className="avatar-container">
                  <img 
                    src={conv.participants[0]?.image || 'default-user.png'} 
                    alt={conv.participants[0]?.name}
                    className="user-avatar"
                  />
                  {conv.unreadCount > 0 && (
                    <span className="unread-badge">{conv.unreadCount}</span>
                  )}
                </div>
                <div className="conversation-details">
                  <div className="conversation-top">
                    <h3>{conv.participants[0]?.name || 'Unknown User'}</h3>
                    <span className="time">
                      {conv.lastMessage?.timestamp 
                        ? new Date(conv.lastMessage.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
                        : ''}
                    </span>
                  </div>
                  <p className="last-message">
                    {conv.lastMessage?.text?.substring(0, 30) || 'No messages yet'}
                    {conv.lastMessage?.text?.length > 30 ? '...' : ''}
                  </p>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Right side - Chat area */}
      <div className="chat-area">
        {selectedConversation ? (
          <>
            <div className="chat-header">
              <div className="chat-partner">
                <img 
                  src={selectedConversation.participants[0]?.image || 'default-user.png'} 
                  alt={selectedConversation.participants[0]?.name}
                  className="chat-avatar"
                />
                <div>
                  <h3>{selectedConversation.participants[0]?.name || 'Unknown User'}</h3>
                  <p className="status">Online</p>
                </div>
              </div>
              <div className="chat-actions">
                <button className="action-btn">
                  <i className="fas fa-phone"></i>
                </button>
                <button className="action-btn">
                  <i className="fas fa-video"></i>
                </button>
                <button className="action-btn">
                  <i className="fas fa-ellipsis-v"></i>
                </button>
              </div>
            </div>

            <div className="messages-container">
              {messages.length === 0 ? (
                <div className="empty-chat">
                  <p>Start a conversation with {selectedConversation.participants[0]?.name || 'this user'}</p>
                </div>
              ) : (
                messages.map((msg) => (
                  <div 
                    key={msg._id} 
                    className={`message ${msg.sender._id === JSON.parse(localStorage.getItem('user'))._id ? 'sent' : 'received'}`}
                  >
                    {msg.sender._id !== JSON.parse(localStorage.getItem('user'))._id && (
                      <img 
                        src={msg.sender.image || 'default-user.png'} 
                        alt={msg.sender.name}
                        className="message-avatar"
                      />
                    )}
                    <div className="message-content">
                      <p>{msg.text}</p>
                      <span className="message-time">
                        {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </span>
                    </div>
                  </div>
                ))
              )}
              <div ref={messagesEndRef} />
            </div>

            <div className="message-input-container">
              <button className="emoji-btn">
                <i className="far fa-smile"></i>
              </button>
              <button className="attach-btn">
                <i className="fas fa-paperclip"></i>
              </button>
              <input
                type="text"
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                placeholder="Type a message..."
                onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
              />
              <button 
                className="send-btn"
                onClick={handleSendMessage}
                disabled={!newMessage.trim()}
              >
                <i className="fas fa-paper-plane"></i>
              </button>
            </div>
          </>
        ) : (
          <div className="no-conversation-selected">
            <div className="welcome-message">
              <h2>Welcome to Messages</h2>
              <p>Select a conversation to start chatting</p>
              <div className="illustration">
                <i className="fas fa-comments"></i>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DMPage;
